static int nib(char c)
{
    return c <= '9' ? c - '0' : (c | 32) - 'a' + 10;
}

static void unhex_sb(const char *s, sb_t *out)
{
    for (; s[0] && s[1]; s += 2) {
        char b = (char)(nib(s[0]) << 4 | nib(s[1]));
        sb_addn(out, &b, 1);
    }
}

static int same_hex(const unsigned char *got, size_t n, const char *want)
{
    sb_t w = {0};
    int ok;

    unhex_sb(want, &w);
    ok = w.len == n && ct_equal(got, w.data, n);
    sb_free(&w);
    return ok;
}

/* Reads one structure with `read` and requires it to use every byte. */
typedef int (*reader_fn)(tls_reader_t *r, int arg);

static int parses(const char *hex, reader_fn read, int arg)
{
    sb_t b = {0};
    tls_reader_t r;
    int ok;

    unhex_sb(hex, &b);
    tls_reader(&r, b.data, b.len);
    ok = read(&r, arg) && tls_done(&r);
    sb_free(&b);
    return ok;
}

static int read_message(tls_reader_t *r, int wire_format)
{
    unsigned wf;
    int ok = mls_message_header(r, &wf) && (int)wf == wire_format;

    if (ok && wf == MLS_WIRE_WELCOME) {
        mls_welcome_t w;
        ok = mls_welcome_read(&w, r);
        if (ok)
            mls_welcome_free(&w);
    } else if (ok && wf == MLS_WIRE_GROUP_INFO) {
        mls_group_info_t gi;
        ok = mls_group_info_read(&gi, r);
    } else if (ok && wf == MLS_WIRE_KEY_PACKAGE) {
        mls_key_package_t kp;
        ok = mls_key_package_read(&kp, r);
        if (ok)
            mls_key_package_free(&kp);
    } else if (ok && wf == MLS_WIRE_PUBLIC) {
        mls_content_t m;
        ok = mls_public_read(&m, r);
    }
    return ok;
}

static int read_tree(tls_reader_t *r, int arg)
{
    mls_tree_t t;
    int ok = mls_tree_parse(&t, r->p, (size_t)(r->end - r->p));

    (void)arg;
    if (ok) {
        mls_tree_free(&t);
        r->p = r->end;
    }
    return ok;
}

static int read_group_secrets(tls_reader_t *r, int arg)
{
    mls_group_secrets_t gs;

    (void)arg;
    return mls_group_secrets_read(&gs, r);
}

static int read_body(tls_reader_t *r, int type)
{
    return mls_proposal_body_read(type, r);
}

static int read_commit(tls_reader_t *r, int arg)
{
    mls_commit_t c;
    int ok = mls_commit_read(&c, r);

    (void)arg;
    if (ok)
        mls_commit_free(&c);
    return ok;
}

static void messages(void)
{
    int ok[6] = {1, 1, 1, 1, 1, 1};

    for (int i = 0; i < (int)(sizeof k_messages / sizeof *k_messages); i++) {
        const messages_t *m = &k_messages[i];
        ok[0] &= parses(m->mls_welcome, read_message, MLS_WIRE_WELCOME) &&
                 parses(m->mls_group_info, read_message, MLS_WIRE_GROUP_INFO) &&
                 parses(m->mls_key_package, read_message, MLS_WIRE_KEY_PACKAGE);
        ok[1] &= parses(m->ratchet_tree, read_tree, 0);
        ok[2] &= parses(m->group_secrets, read_group_secrets, 0);
        ok[3] &= parses(m->add_proposal, read_body, MLS_PROPOSAL_ADD) &&
                 parses(m->update_proposal, read_body, MLS_PROPOSAL_UPDATE) &&
                 parses(m->remove_proposal, read_body, MLS_PROPOSAL_REMOVE) &&
                 parses(m->pre_shared_key_proposal, read_body, MLS_PROPOSAL_PSK) &&
                 parses(m->re_init_proposal, read_body, MLS_PROPOSAL_REINIT) &&
                 parses(m->external_init_proposal, read_body, MLS_PROPOSAL_EXTERNAL_INIT) &&
                 parses(m->group_context_extensions_proposal, read_body,
                        MLS_PROPOSAL_GROUP_CONTEXT_EXTENSIONS);
        ok[4] &= parses(m->commit, read_commit, 0);
        ok[5] &= parses(m->public_message_application, read_message, MLS_WIRE_PUBLIC) &&
                 parses(m->public_message_proposal, read_message, MLS_WIRE_PUBLIC) &&
                 parses(m->public_message_commit, read_message, MLS_WIRE_PUBLIC);
    }
    check(ok[0], "welcome, group info and key package messages");
    check(ok[1], "ratchet trees");
    check(ok[2], "group secrets");
    check(ok[3], "proposals");
    check(ok[4], "commits");
    check(ok[5], "public messages");
}

static void transcript(void)
{
    sb_t raw = {0}, interim = {0};
    tls_reader_t r;
    mls_content_t m;
    unsigned char confirmed[32], next[32], key[32], tag[32];
    int ok;

    unhex_sb(k_th_content, &raw);
    unhex_sb(k_th_interim_before, &interim);
    tls_reader(&r, raw.data, raw.len);
    ok = mls_auth_content_read(&m, &r) && tls_done(&r) && m.content_type == MLS_CONTENT_COMMIT;
    check(ok, "authenticated content");
    if (ok) {
        mls_transcript(interim.data, interim.len, &m, confirmed, next);
        check(same_hex(confirmed, 32, k_th_confirmed_after) && same_hex(next, 32, k_th_interim_after),
              "transcript hashes");
        for (int k = 0; k < 32; k++)
            key[k] = (unsigned char)(nib(k_th_confirmation_key[2 * k]) << 4 | nib(k_th_confirmation_key[2 * k + 1]));
        hmac256(key, 32, confirmed, 32, tag);
        check(m.confirmation_tag.n == 32 && ct_equal(tag, m.confirmation_tag.p, 32), "confirmation tag");
    }
    sb_free(&raw);
    sb_free(&interim);
}

static void psk_secrets(void)
{
    int ok = 1;

    for (int i = 0; i < (int)(sizeof k_psks / sizeof *k_psks); i++) {
        const psk_case_t *c = &k_psks[i];
        sb_t ids[16] = {{0}}, keys[16] = {{0}};
        mls_bytes_t id[16], key[16];
        unsigned char secret[32];
        for (int k = 0; k < c->n; k++) {
            sb_t v = {0};
            tls_u8(&ids[k], 1); /* external */
            unhex_sb(c->id[k], &v);
            tls_vec(&ids[k], v.data, v.len);
            sb_clear(&v);
            unhex_sb(c->nonce[k], &v);
            tls_vec(&ids[k], v.data, v.len);
            sb_free(&v);
            unhex_sb(c->key[k], &keys[k]);
            id[k].p = (const unsigned char *)ids[k].data;
            id[k].n = ids[k].len;
            key[k].p = (const unsigned char *)keys[k].data;
            key[k].n = keys[k].len;
        }
        ok &= mls_psk_secret(id, key, c->n, secret) && same_hex(secret, 32, c->secret);
        for (int k = 0; k < c->n; k++) {
            sb_free(&ids[k]);
            sb_free(&keys[k]);
        }
    }
    check(ok, "psk secrets");
}

void entry(void)
{
    messages();
    transcript();
    psk_secrets();
    finish();
}
